%[text] # Tutorial on St. Venant principals\\
%%
%[text] ## Problem 1
%[text] 
% Equilateral triangular cross section 
clear; 
% Prandtl's stress function : 

syms x y phi G K a
phi = G*K*(0.5*(x^2+y^2)-(x^3-3*x*y^2)/(2*a)-2*a^2/27) %[output:29c8bb8c]
t_xz = diff(phi,y) %[output:4da9eb93]
t_yz = diff(phi,x) %[output:6f3ec0dd]
%%
%[text] ## Defining the zone

a=1; G=1; K=1;
N = 501;

x = linspace(-a/3,2*a/3,N);
y = linspace(-a/sqrt(3),a/sqrt(3),N);

[X,Y] = meshgrid(x,y);


inside = (X >= -a/3) & ...
    (Y <= (2*a/3-X)/sqrt(3)) & ...
    (Y >= -(2*a/3-X)/sqrt(3));

tau_xz = -G*K*(Y+3*X.*Y/a);  tau_yz= G*K*(X-(3.*X.^2-3.*Y.^2)/(2*a));
% actually it is the Phi/(GK) though I haver chosen G=K=1
Phi = -G*K*(0.5*(X.^2 + Y.^2) - (X.^3 - 3*X.*Y.^2)/(2*a) - 2*a^2/27);
tau_xz(~inside) = NaN;
tau_yz(~inside) = NaN;
tau = sqrt(tau_xz.^2 + tau_yz.^2);
Phi(~inside) = NaN;

% PLOT PRANDTL STRESS FUNCTION
figure('Color','w');

surf(X,Y,Phi,'EdgeColor','none');
daspect([1 1 0.2]); colorbar;
xlabel('x (m)');
ylabel('y (m)');
zlabel('Stress Function Distribution');
% 3D shear stress resultant5 plot 
figure('Color','w'); %[output:443e8560]

surf(X, Y, tau, tau, ... %[output:443e8560]
    'EdgeColor','none'); %[output:443e8560]

daspect([1 1 1]); %[output:443e8560]
colorbar; %[output:443e8560]
xlabel('x (m)'); %[output:443e8560]
ylabel('y (m)'); %[output:443e8560]
zlabel('Resultant shear stress (MPa)'); %[output:443e8560]
surf(X, Y, tau_xz, tau_xz, ... %[output:3f7d6cd4]
    'EdgeColor','none'); %[output:3f7d6cd4]

daspect([1 1 1]); %[output:3f7d6cd4]
colorbar; %[output:3f7d6cd4]
xlabel('x (m)'); %[output:3f7d6cd4]
ylabel('y (m)'); %[output:3f7d6cd4]
zlabel('\tau_{xz} shear stress (MPa)'); %[output:3f7d6cd4]

surf(X, Y, tau_yz, tau_yz, ...
    'EdgeColor','none');

daspect([1 1 1]);
colorbar;
xlabel('x (m)');
ylabel('y (m)');
zlabel('\tau_{yz} shear stress (MPa)');
% PLOT SHEAR-STRESS VECTORS
% Subsample the grid to keep the arrows readable

figure('Color','w');

skip = 25;
Xs = X(1:skip:end,1:skip:end);
Ys = Y(1:skip:end,1:skip:end);

Tx = tau_xz(1:skip:end,1:skip:end);
Ty = tau_yz(1:skip:end,1:skip:end);

quiver(Xs,Ys,Tx,Ty,'k');
hold on;


axis equal;
grid on;
xlabel('x (m)');
ylabel('y (m)');
title('Shear-Stress Component Field');


% PLOT RESULTANT SHEAR-STRESS CONTOUR
figure('Color','w');

contourf(X,Y,tau/1e6,30,'LineColor','none');
colormap("turbo")
hold on;
axis equal;
grid on;
colorbar;
xlabel('x (m)');
ylabel('y (m)');
title('Resultant Distribution (MPa)');

% PLOT Tau_xz SHEAR-STRESS CONTOUR
figure('Color','w');

contourf(X,Y,tau_xz/1e6,30,'LineColor','none');
colormap("turbo")
hold on;
axis equal;
grid on;
colorbar;
xlabel('x (m)');
ylabel('y (m)');
title('\tau_{xz} Distribution (MPa)');
% PLOT tau_yz SHEAR-STRESS CONTOUR
figure('Color','w');

contourf(X,Y,tau_yz/1e6,30,'LineColor','none');
colormap("turbo")
hold on;
axis equal;
grid on;
colorbar;
xlabel('x (m)');
ylabel('y (m)');
title('\tau_{yz} Distribution (MPa)');
fprintf('Resultant stress at centroid = %.6e Pa\n', min(min(tau))); %[output:2c631608]
fprintf(' Maximum Resultant stress  = %.6e Pa\n', max(max(tau))); %[output:635ee297]
%%
%[text] ## Problem 2 : Open Thin walled section
T = 100;              % Applied torque (N.m)
G = 80e9;             % Shear modulus (Pa)
a = 0.20;             % Web length (m)
b = 0.10;             % Flange length (m)
t = 0.002;            % Thin-wall thickness (m)

alpha = 30*pi/180;    % Inclination of top strip

% TORSIONAL CONSTANT OF EACH STRIP
J_web = (1/3)*a*t^3;
J_top = (1/3)*b*t^3;
J_bottom = (1/3)*b*(2*t)^3;

J_total = J_web + J_top + J_bottom; K = T/(G*J_total);
tau_web = G*K*t;
tau_top = G*K*t;
tau_bottom = G*K*(2*t);  tau_max = max([tau_web,tau_top,tau_bottom]);

% creating the thin walled c/s
bottom = polyshape([0 b b 0],[0 0 2*t 2*t]);
web = polyshape([0 0 t t],[0 a a 0]);
figure(1);
A = union(bottom,web);
plot(A);

%%
%[text] ## Problem 4



%%
%[text] ## Elliptical c/s
clear all; 
T=1000;  G=70e9;  % N and Pa
% major axis : a & minor axis: b
a=1; b=1*0.5;

% create a elliptical mesh grid
N = 501;

x = linspace(-a,a,N);
y = linspace(-b,b,N);

[X,Y] = meshgrid(x,y);

% Points inside the ellipse
inside = (X.^2/a^2 + Y.^2/b^2) <= 1;

% Torsional Constant 
J = pi*(a*b)^3/(a^2+b^2);

% Prandtl's stress function 
syms  phi x_ y_ a_ b_

phi = -T*((x_/a_)^2+(y_/b_)^2 -1)/(pi*a_*b_) %[output:39825276]
t_xz = diff(phi,y_) %[output:549ae5d7]
t_yz = -diff(phi,x_) %[output:55d3ad4d]
tau_xz = -2000*Y/(pi*a*b^3) ;  tau_yz = 2000*X/(pi*a^3*b^1); 
tau = sqrt(tau_xz.^2 + tau_yz.^2);

Phi = (T/(pi*a*b)).*(1 - X.^2/a^2 - Y.^2/b^2);
% Remove values outside the ellipse
tau_xz(~inside) = NaN;
tau_yz(~inside) = NaN;
tau(~inside) = NaN;
Phi(~inside) =NaN;



% PLOT RESULTANT SHEAR-STRESS CONTOUR
figure('Color','w'); %[output:87b46ea8]

contourf(X,Y,tau/1e6,30,'LineColor','none'); %[output:87b46ea8]
colormap("turbo") %[output:87b46ea8]
hold on; %[output:87b46ea8]

plot(a*cos(linspace(0,2*pi,1000)), ... %[output:87b46ea8]
     b*sin(linspace(0,2*pi,1000)), ... %[output:87b46ea8]
     'k','LineWidth',1.5); %[output:87b46ea8]

axis equal; %[output:87b46ea8]
grid on; %[output:87b46ea8]
colorbar; %[output:87b46ea8]

xlabel('x (m)'); %[output:87b46ea8]
ylabel('y (m)'); %[output:87b46ea8]
title('Resultant Shear Stress (MPa)'); %[output:87b46ea8]

%%\ 10. PLOT tau_xz DISTRIBUTION
figure('Color','w'); %[output:214503fd]

contourf(X,Y,tau_xz/1e6,30,'LineColor','none'); %[output:214503fd]
hold on; %[output:214503fd]

plot(a*cos(linspace(0,2*pi,500)), ... %[output:214503fd]
     b*sin(linspace(0,2*pi,500)), ... %[output:214503fd]
     'k','LineWidth',1.5); %[output:214503fd]

axis equal; %[output:214503fd]
grid on; %[output:214503fd]
colorbar; %[output:214503fd]

xlabel('x (m)'); %[output:214503fd]
ylabel('y (m)'); %[output:214503fd]
title('\tau_{xz} Distribution (MPa)'); %[output:214503fd]

%%\ 11. PLOT tau_yz DISTRIBUTION
figure('Color','w'); %[output:7dec49a6]

contourf(X,Y,tau_yz/1e6,30,'LineColor','none'); %[output:7dec49a6]
hold on; %[output:7dec49a6]

plot(a*cos(linspace(0,2*pi,500)), ... %[output:7dec49a6]
     b*sin(linspace(0,2*pi,500)), ... %[output:7dec49a6]
     'k','LineWidth',1.5); %[output:7dec49a6]

axis equal; %[output:7dec49a6]
grid on; %[output:7dec49a6]
colorbar; %[output:7dec49a6]

xlabel('x (m)'); %[output:7dec49a6]
ylabel('y (m)'); %[output:7dec49a6]
title('\tau_{yz} Distribution (MPa)'); %[output:7dec49a6]

% PLOT SHEAR-STRESS VECTORS
% Subsample the grid to keep the arrows readable

figure('Color','w'); %[output:8481e140]

skip = 15;
Xs = X(1:skip:end,1:skip:end);
Ys = Y(1:skip:end,1:skip:end);

Tx = tau_xz(1:skip:end,1:skip:end);
Ty = tau_yz(1:skip:end,1:skip:end);

quiver(Xs,Ys,Tx,Ty,'k'); %[output:8481e140]
hold on; %[output:8481e140]

plot(a*cos(linspace(0,2*pi,500)), ... %[output:8481e140]
     b*sin(linspace(0,2*pi,500)), ... %[output:8481e140]
     'r','LineWidth',2); %[output:8481e140]

axis equal; %[output:8481e140]
grid on; %[output:8481e140]
xlabel('x (m)'); %[output:8481e140]
ylabel('y (m)'); %[output:8481e140]
title('Shear-Stress Component Field'); %[output:8481e140]

% STRESS ALONG THE MAJOR AXIS
x_axis = linspace(-a,a,501);
y_axis = zeros(size(x_axis));

tau_axis = sqrt( ...
    (-2*T*y_axis/(pi*a*b^3)).^2 + ...
    ( 2*T*x_axis/(pi*a^3*b)).^2 );

figure('Color','w'); %[output:728c7776]

plot(x_axis,tau_axis/1e6,'b','LineWidth',2); %[output:728c7776]
hold on; %[output:728c7776]
grid on; %[output:728c7776]

xlabel('x (m)'); %[output:728c7776]
ylabel('Resultant shear stress (MPa)'); %[output:728c7776]
title('Shear Stress Along the Major Axis'); %[output:728c7776]
% STRESS ALONG THE Minor AXIS

y_axis = linspace(-b,b,501);
x_axis = zeros(size(y_axis));

tau_axis = sqrt( ...
    (-2*T*y_axis/(pi*a*b^3)).^2 + ...
    ( 2*T*x_axis/(pi*a^3*b)).^2 );

figure('Color','w'); %[output:83c59c37]

plot(y_axis,tau_axis/1e6,'r','LineWidth',2); %[output:83c59c37]
grid on; %[output:83c59c37]

xlabel('x (m)'); %[output:83c59c37]
ylabel('Resultant shear stress (MPa)'); %[output:83c59c37]
title('Shear Stress Along the Minor Axis'); %[output:83c59c37]
hold off; %[output:83c59c37]


%%\ 14. VERIFY MAXIMUM NUMERICALLY
fprintf('Numerical maximum on grid = %.6f MPa\n', ... %[output:group:4ee8a6c5] %[output:8a6de5c1]
        max(tau(:))/1e6); %[output:group:4ee8a6c5] %[output:8a6de5c1]
%%
%[text] ## Warping Phenomenon
% In notes we get 
W  = (T*(b^2-a^2)/(G*pi*a^3*b^3)).*(X.*Y);
W(~inside)=NaN;
figure('Color','w'); %[output:0802e24e]

contourf(X,Y,W,30,'LineColor','none'); %[output:0802e24e]
colormap("turbo") %[output:0802e24e]
hold on; %[output:0802e24e]

plot(a*cos(linspace(0,2*pi,1000)), ... %[output:0802e24e]
    b*sin(linspace(0,2*pi,1000)), ... %[output:0802e24e]
    'k','LineWidth',1.5); %[output:0802e24e]

axis equal; %[output:0802e24e]
grid on; %[output:0802e24e]
colorbar; %[output:0802e24e]

xlabel('x (m)'); %[output:0802e24e]
ylabel('y (m)'); %[output:0802e24e]
title('Warping Field'); %[output:0802e24e]
%%
%[text] ## 3D plot

%%\ 3D plot
figure('Color','w'); %[output:9b0f0662]

surf(X,Y,Phi,'EdgeColor','none'); %[output:9b0f0662]
hold on; %[output:9b0f0662]
xlabel('x (m)'); %[output:9b0f0662]
ylabel('y (m)'); %[output:9b0f0662]
zlabel('Stress Function Distribution'); %[output:9b0f0662]
%%\ 3D plot
figure('Color','w'); %[output:4e893910]

surf(X,Y,W,'EdgeColor','none'); %[output:4e893910]
hold on; %[output:4e893910]
xlabel('x (m)'); %[output:4e893910]
ylabel('y (m)'); %[output:4e893910]
zlabel('Warping Field  Distribution'); %[output:4e893910]

figure('Color','w'); %[output:7aac0570]

surf(X, Y, tau_xz/1e6, tau_xz/1e6, ... %[output:7aac0570]
    'EdgeColor','none'); %[output:7aac0570]
xlabel('x (m)'); %[output:7aac0570]
ylabel('y (m)'); %[output:7aac0570]
zlabel('tau_xz shear stress (MPa)'); %[output:7aac0570]
figure('Color','w'); %[output:5afed4d6]

surf(X, Y, tau_yz/1e6, tau_yz/1e6, ... %[output:5afed4d6]
    'EdgeColor','none'); %[output:5afed4d6]
xlabel('x (m)'); %[output:5afed4d6]
ylabel('y (m)'); %[output:5afed4d6]
zlabel('tau_yz shear stress (MPa)'); %[output:5afed4d6]

figure('Color','w'); %[output:035f21bc]

surf(X, Y, tau, tau, ... %[output:035f21bc]
    'EdgeColor','none'); %[output:035f21bc]

hold on; %[output:035f21bc]
theta = linspace(0,2*pi,500);

xb = a*cos(theta);
yb = b*sin(theta);

tau_boundary = sqrt( ...
    (2*T*yb/(pi*a*b^3)).^2 + ...
    (2*T*xb/(pi*a^3*b)).^2 );

plot3(xb, yb, tau_boundary, ... %[output:035f21bc]
    'k-', 'LineWidth', 1.8); %[output:035f21bc]

xlabel('x (m)'); %[output:035f21bc]
ylabel('y (m)'); %[output:035f21bc]
zlabel('Resultant shear stress (MPa)'); %[output:035f21bc]

